 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.earyRedmptValuDdList = undefined; try { scwin.earyRedmptValuDdList = /* sdd-asis-lifecycle:begin earyRedmptValuDdList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil70903' }); }

scwin.earyRedmptBas1IdxList = undefined; try { scwin.earyRedmptBas1IdxList = /* sdd-asis-lifecycle:begin earyRedmptBas1IdxList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil70903' }); }

scwin.earyRedmptBas2IdxList = undefined; try { scwin.earyRedmptBas2IdxList = /* sdd-asis-lifecycle:begin earyRedmptBas2IdxList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil70903' }); }

scwin.earyRedmptPrcList = undefined; try { scwin.earyRedmptPrcList = /* sdd-asis-lifecycle:begin earyRedmptPrcList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil70903' }); }

scwin.earyRedmptPayDdList = undefined; try { scwin.earyRedmptPayDdList = /* sdd-asis-lifecycle:begin earyRedmptPayDdList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil70903' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70903.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

